bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
root=/home/gace/.local/share/gace-create-videobot/native-sticker-c8c50d420c0b9b5d447a1fc87ef3d9e1ec7aceed/deploy
compose="$root/compose.videobot.poll.yaml"
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true
old_image="$(docker inspect "$cid" --format '{{.Image}}')"
test "$(docker image inspect create-videobot:video-sale-1695 --format '{{.Id}}')" = "$old_image"
test -f "$compose"
stage="$(mktemp -d /tmp/gace-video-receipt-fix.XXXXXX)"
trap 'rm -rf "$stage"' EXIT
docker cp "$cid:/opt/videobot/src/sales/pgPostingReceipts.mjs" "$stage/pgPostingReceipts.mjs"
python3 - "$stage/pgPostingReceipts.mjs" <<'PY'
from pathlib import Path
import sys
p=Path(sys.argv[1]);s=p.read_text()
old="""      return {status:row.status,freeMessageIds:row.free_message_ids ?? null,
        paidMessageId:row.paid_message_id==null?null:Number(row.paid_message_id)};"""
new="""      const freeMessageIds=row.free_message_ids==null?null:row.free_message_ids.map(value=>{
        const n=Number(value);
        if(!Number.isSafeInteger(n)||n<=0)throw new Error('PERSISTED_FREE_MESSAGE_ID_INVALID');
        return n;
      });
      return {status:row.status,freeMessageIds,
        paidMessageId:row.paid_message_id==null?null:Number(row.paid_message_id)};"""
if s.count(old)!=1:raise SystemExit('RECEIPT_SOURCE_BASELINE_MISMATCH')
p.write_text(s.replace(old,new))
PY
chmod 644 "$stage/pgPostingReceipts.mjs"
docker exec -i "$cid" node --input-type=module --check < "$stage/pgPostingReceipts.mjs"
docker tag "$old_image" create-videobot:video-receipt-base-1695
printf 'FROM create-videobot:video-receipt-base-1695\nCOPY pgPostingReceipts.mjs /opt/videobot/src/sales/pgPostingReceipts.mjs\n' > "$stage/Dockerfile"
docker build --network none --pull=false -t create-videobot:video-sale-1695-receipt-fixed "$stage" >/dev/null
docker run --rm --network none --entrypoint node create-videobot:video-sale-1695-receipt-fixed --input-type=module -e '
import {createPostgresPostingReceiptStore} from "./src/sales/pgPostingReceipts.mjs";
const store=createPostgresPostingReceiptStore({query:async()=>({rows:[{status:"sent",free_message_ids:["4689","4690"],paid_message_id:"4691"}]})});
const r=await store.read("video1:1");
if(r.freeMessageIds[0]!==4689||r.freeMessageIds[1]!==4690||r.paidMessageId!==4691)process.exit(5);
console.log("RECEIPT_BIGINT_ARRAY_FIX_TEST=PASS");
'
backup="$compose.video-receipt-1695.backup"
test ! -e "$backup"
cp -p "$compose" "$backup"
rollback(){ cp -p "$backup" "$compose"; (cd "$root" && docker compose -p gace-createvdobot -f "$compose" up -d --no-deps --no-build --force-recreate videobot-poll) >/dev/null 2>&1 || true; }
trap 'rollback; rm -rf "$stage"' EXIT
python3 - "$compose" <<'PY'
from pathlib import Path
import sys,re
p=Path(sys.argv[1]);lines=p.read_text().splitlines(keepends=True)
start=next((i for i,x in enumerate(lines) if re.match(r'^  videobot-poll:\s*$',x.rstrip())),None)
if start is None:raise SystemExit('SERVICE_MISSING')
end=next((i for i in range(start+1,len(lines)) if re.match(r'^  [\w-]+:\s*$',lines[i].rstrip())),len(lines))
matches=[i for i in range(start+1,end) if re.match(r'^    image:\s*',lines[i])]
if len(matches)!=1 or 'create-videobot:video-sale-1695' not in lines[matches[0]]:
 raise SystemExit('IMAGE_IDENTITY_MISMATCH')
lines[matches[0]]=lines[matches[0]].replace('create-videobot:video-sale-1695','create-videobot:video-sale-1695-receipt-fixed')
p.write_text(''.join(lines))
PY
(cd "$root" && docker compose -p gace-createvdobot -f "$compose" config --quiet)
(cd "$root" && docker compose -p gace-createvdobot -f "$compose" up -d --no-deps --no-build --force-recreate videobot-poll) >/dev/null
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true
test "$(docker inspect "$cid" --format '{{.Image}}')" = "$(docker image inspect create-videobot:video-sale-1695-receipt-fixed --format '{{.Id}}')"
docker exec -i "$cid" node --input-type=module <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {createPostgresPostingReceiptStore} from '/opt/videobot/src/sales/pgPostingReceipts.mjs';
const e=process.env;
if(e.VIDEOBOT_VIDEO_SALE_THREAD_ID!=='1695')throw Error('TOPIC_ENV_INVALID');
const pass=readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim();
const url='postgresql://'+encodeURIComponent(e.VIDEOBOT_DB_USER)+':'+encodeURIComponent(pass)+'@'+e.VIDEOBOT_DB_HOST+':5432/'+e.VIDEOBOT_DB_NAME;
const pool=new pg.Pool({connectionString:url,max:1,connectionTimeoutMillis:5000});
try{
 const r=await pool.query("SELECT listing_id,status,revision FROM videobot_listings WHERE listing_id=$1",['389558ba-a38b-42a1-b92e-e98143df3e2d']);
 if(r.rowCount!==1||r.rows[0].status!=='published'||Number(r.rows[0].revision)!==2)throw Error('LISTING_READBACK_MISMATCH');
 const saved=await createPostgresPostingReceiptStore(pool).read('389558ba-a38b-42a1-b92e-e98143df3e2d:1');
 if(saved?.status!=='sent'||saved.freeMessageIds?.[0]!==4689||saved.freeMessageIds?.[1]!==4690||saved.paidMessageId!==4691)throw Error('LIVE_MESSAGE_RECEIPT_MISMATCH');
 console.log('VIDEO_POSTED_AND_RECEIPT_NORMALIZED=PASS');
}finally{await pool.end()}
NODE
for i in 1 2 3 4 5 6 7 8; do
 if docker logs "$cid" --tail 160 2>&1 | grep -q 'CREATOR_DM_POLL_READY=PASS' && docker logs "$cid" --tail 160 2>&1 | grep -q 'STICKER_SHOP_HTTP_READY=PASS'; then break;fi
 sleep 2
done
docker logs "$cid" --tail 160 2>&1 | grep -q 'CREATOR_DM_POLL_READY=PASS'
docker logs "$cid" --tail 160 2>&1 | grep -q 'STICKER_SHOP_HTTP_READY=PASS'
trap - EXIT
rm -rf "$stage"
echo VIDEO_RECEIPT_LIVE_PATCH=PASS
echo VIDEO_AND_STICKER_POLL_READY=PASS
